const rawOutput = $input.item.json.output || $input.item.json.text || "";
let aiOutput = {};

if (typeof rawOutput === 'object') {
  aiOutput = rawOutput;
} else {
  const jsonMatch = rawOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try { aiOutput = JSON.parse(jsonMatch[0]); } catch (e) { aiOutput = {}; }
  }
}

const summary = aiOutput.summary || "Software Engineer experienced in building production-grade <strong>TypeScript</strong> and <strong>React</strong> SaaS applications end-to-end. Built and shipped <strong>BillPharma</strong>, a multi-tenant platform featuring offline-first workflows, RBAC, and AI-assisted inventory tools. Experienced in developing <strong>interactive UI features</strong>, client-facing verification flows, and <strong>REST API integrations</strong> across production applications. Strong background in <strong>workflow automations</strong>, AWS deployment, and clean component architecture.";

const defaultSkills = [
  { label: "Languages", items: "TypeScript, JavaScript (ES6+), Java, C++, Python" },
  { label: "Frontend", items: "React.js, Next.js, Monaco Editor / CodeMirror Integration, HTML5, CSS3, Tailwind CSS, Component Architecture" },
  { label: "Backend", items: "Node.js, Express.js, REST API Design, Authentication (JWT, OAuth), Webhook Integrations" },
  { label: "Databases", items: "MongoDB, Mongoose, PostgreSQL (Basics)" },
  { label: "System & Core", items: "Data Structures & Algorithms, API Design, Dynamic UI State Management, Multi-Tenant Architecture" },
  { label: "DevOps & Open Source", items: "Git, GitHub, Postman, AWS (EC2), Docker (Basics), CI/CD (GitHub Actions), Netlify, Render" },
  { label: "AI & Cloud Integrations", items: "n8n Workflow Automation, Webhook Pipelines, Prompt Engineering, Generative AI Integration (Gemini API/Vision), RAG/AI-assisted Tooling" }
];

const skills = Array.isArray(aiOutput.skills) && aiOutput.skills.length ? aiOutput.skills.slice(0, 7) : defaultSkills;

const rcgeminiBullets = aiOutput.rcgemini_bullets || [
  "Delivered <strong>4 production-ready MERN applications</strong> within a 3-member team, owning feature development, debugging, and deployment workflows.",
  "Built responsive <strong>React.js</strong> interfaces and reusable component systems, reducing development cycle time by 30% and improving cross-platform consistency.",
  "Developed admin dashboards and real-time data workflows, improving operational visibility and system usability.",
  "Engineered the <strong>WealthX</strong> platform with QR-based payments, client payment verification, and role-based access, driving completed transactions by 40%.",
  "Contributed to internal <strong>CRM development</strong> with secure authentication and task tracking, increasing team throughput by 30%."
];

const koduBullets = aiOutput.kodu_bullets || [
  "Developed full-stack features using <strong>React.js</strong>, <strong>Node.js</strong>, and <strong>MongoDB</strong>, improving application usability and responsiveness.",
  "Optimized frontend architecture using reusable components, cut development time by 30% while improving cross-device compatibility.",
  "Identified and fixed application-level defects, reducing reported bugs by 15% and improving system performance by 25%."
];

const defaultBillpharma = {
  name: "BillPharma — Multi-Tenant Pharmacy Management SaaS, Solo Developer",
  link: "billpharma.netlify.app",
  date: "Dec, 2025 – Present",
  tech: "TypeScript, React.js, Node.js, Express.js, MongoDB, AI Integration, Service Workers, Tailwind CSS",
  bullets: [
    "Designed and deployed a <strong>production-grade multi-tenant SaaS platform</strong> for pharmacy operations, handling inventory, billing, GST compliance, and financial analytics.",
    "Engineered <strong>offline-first billing</strong> using <strong>Service Workers</strong> and client-side storage, ensuring uninterrupted invoice generation during network failures.",
    "Implemented <strong>tenant-isolated architecture</strong> with <strong>role-based access control (RBAC)</strong>, enabling secure multi-organization usage within a single system.",
    "Integrated <strong>AI-assisted inventory forecasting</strong> and billing workflows, reducing manual data entry effort by ~60% and improving operational accuracy.",
    "Built scalable <strong>REST APIs</strong> and optimized frontend performance, ensuring fast and reliable user experience across modules.",
    "Engineered interactive UI control panels and real-time state extraction tools for complex multi-field forms, improving data entry speed by 40%.",
    "Established GST-compliant invoicing with automated tax calculations aligned with Indian regulatory requirements."
  ]
};

const defaultSecondProject = {
  name: "AI Job Email & WhatsApp Automation (n8n, AWS)",
  link: "",
  date: "Sep, 2025",
  tech: "",
  bullets: [
    "Engineered an automated email filtering and labeling workflow using <strong>n8n</strong> and <strong>Gmail API</strong> hosted on <strong>AWS</strong> to isolate high-priority job opportunities in real time.",
    "Integrated <strong>WhatsApp API webhooks</strong> to trigger instant alerts and auto-respond with tailored CVs or details upon client/recruiter request.",
    "Structured prompt parsing and payload validation rules to extract key action items and minimize manual response latency.",
    "Deployed and maintained self-hosted n8n workflows on <strong>AWS EC2</strong>, ensuring stable webhook processing and operational uptime."
  ]
};

let projects = Array.isArray(aiOutput.projects) && aiOutput.projects.length ? aiOutput.projects.slice(0, 3) : [defaultBillpharma, defaultSecondProject];

const hasBillpharma = projects.some(p => (p.name || "").toLowerCase().includes("billpharma"));
if (!hasBillpharma) projects.unshift(defaultBillpharma);

// Enforce minimum 2 projects — never BillPharma alone
if (projects.length < 2) {
  projects.push(defaultSecondProject);
}
projects = projects.slice(0, 3);

// Enforce fixed dates, links, and strip tech line from non-BillPharma projects
projects = projects.map(p => {
  const n = (p.name || "").toLowerCase();
  let updated = { ...p };
  if (n.includes("wealthx")) {
    updated.link = "rcgemini-wealthx.netlify.app";
    updated.date = "June, 2025";
  }
  if (n.includes("job email") || n.includes("ai cv generator")) updated.date = "Sep, 2025";
  if (n.includes("whatsapp ai agent")) updated.date = "Aug, 2025";
  if (!n.includes("billpharma")) updated.tech = "";
  return updated;
});

const renderProject = (p) => `
  <div class="item-row">
    <span class="item-title">${p.name || ""}${p.link ? ` (<a href="https://${p.link}">${p.link}</a>)` : ""}</span>
    <span class="item-date">${p.date || ""}</span>
  </div>
  <ul class="bullet-list">
    ${(p.bullets || []).map(b => `<li>${b}</li>`).join('')}
  </ul>
  ${p.tech ? `<div class="tech-stack"><strong>Tech:</strong> ${p.tech}</div>` : ""}
`;

const renderSkills = (skillsArr) => skillsArr.map(s => `<li>• <strong>${s.label}:</strong> ${s.items}</li>`).join('');

const htmlTemplate = `
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 7.9pt;
    line-height: 1.28;
    color: #333;
    padding: 17px 22px;
  }

  .header { text-align: center; margin-bottom: 8px; }
  .header h1 { font-size: 18pt; font-weight: bold; margin-bottom: 2px; color: #1a365d; }
  .header .contact-line { font-size: 8.5pt; color: #555; }
  .header a { color: #2b6cb0; text-decoration: none; }

  h2.section-title {
    font-size: 9.0pt;
    font-weight: bold;
    text-transform: uppercase;
    border-bottom: 1.5px solid #2b6cb0;
    color: #2b6cb0;
    margin-top: 8px;
    margin-bottom: 4px;
    padding-bottom: 1px;
    letter-spacing: 0.4px;
  }

  p { font-size: 8.0pt; margin-bottom: 3px; text-align: justify; color: #333; }

  .skills-list { list-style: none; padding-left: 0; margin-bottom: 3px; }
  .skills-list li { font-size: 8.5pt; margin-bottom: 2px; line-height: 1.25; color: #333; }

  .item-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    font-size: 8.4pt;
    margin-top: 4px;
  }
  .item-title { font-weight: bold; color: #1a365d; }
  .item-date { font-weight: normal; font-size: 8pt; color: #666; white-space: nowrap; }
  .item-subtitle { font-style: italic; font-size: 8pt; color: #555; margin-bottom: 2px; }

  ul.bullet-list { padding-left: 14px; margin-bottom: 3px; }
  ul.bullet-list li { font-size: 8.4pt; margin-bottom: 1.5px; text-align: justify; color: #333; }

  .tech-stack { font-size: 8pt; margin-top: 2px; margin-bottom: 3px; color: #555; }

  a { color: #2b6cb0; text-decoration: none; }
</style>
</head>
<body>

  <div class="header">
    <h1>Manish Kumar Yadav</h1>
    <div class="contact-line">
      manishkyadav969@gmail.com | +91-7404775037 |
      <a href="[https://github.com/Manish-Yadav77](https://github.com/Manish-Yadav77)">GitHub</a> |
      <a href="[https://www.linkedin.com/in/manish-yadav-fullstack-mern/](https://www.linkedin.com/in/manish-yadav-fullstack-mern/)">LinkedIn</a> |
      <a href="[https://manishportfolio7.netlify.app](https://manishportfolio7.netlify.app)">Portfolio</a> |
      Rohtak, Haryana
    </div>
  </div>

  <h2 class="section-title">PROFESSIONAL SUMMARY</h2>
  <p>${summary}</p>

  <h2 class="section-title">SKILLS</h2>
  <ul class="skills-list">
    ${renderSkills(skills)}
  </ul>

  <h2 class="section-title">EXPERIENCE</h2>

  <div class="item-row">
    <span class="item-title">Full Stack Developer, RCGemini, Hisar, IN</span>
    <span class="item-date">Apr, 2025 – Present</span>
  </div>
  <ul class="bullet-list">
    ${rcgeminiBullets.map(b => `<li>${b}</li>`).join('')}
  </ul>

  <div class="item-row">
    <span class="item-title">Full Stack Developer Intern, Kodu-Powered by Dhurina, Hisar, IN</span>
    <span class="item-date">Oct, 2024 – Apr, 2025</span>
  </div>
  <ul class="bullet-list">
    ${koduBullets.map(b => `<li>${b}</li>`).join('')}
  </ul>

  <h2 class="section-title">PROJECTS</h2>
  ${projects.map(renderProject).join('')}

  <h2 class="section-title">EDUCATION & CERTIFICATIONS</h2>

  <div class="item-row">
    <span class="item-title">Full Stack Development Program + Internship, Hisar, Haryana</span>
    <span class="item-date">Apr, 2025</span>
  </div>
  <div class="item-subtitle">Kodu (Powered by Dhurina)</div>
  <ul class="bullet-list">
    <li>Completed a 1-year Full Stack Development Program followed by a 6-month Full Stack Developer Internship, building multiple MERN applications with one selected for production deployment.</li>
  </ul>

  <div class="item-row" style="margin-top: 3px;">
    <span class="item-title">Bachelor of Computer Application (BCA)</span>
    <span class="item-date">Dec, 2024</span>
  </div>
  <div class="item-subtitle">Maharshi Dayanand University (MDU), Rohtak</div>
  <ul class="bullet-list">
    <li>Coursework: Java, C++, DBMS, Operating Systems, Computer Networks, Object-Oriented Programming</li>
  </ul>

</body>
</html>
`;

return {
  json: {
    html: htmlTemplate,
    summary,
    skills,
    rcgemini_bullets: rcgeminiBullets,
    kodu_bullets: koduBullets,
    projects
  }
};
